package com.transiva.app;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.Build;import android.provider.Settings;
public final class TransAssistantActions { private TransAssistantActions(){} public static void run(Activity a,String action){ if(action==null)return; Intent i=null; switch(action){case"OPEN_RIDE":i=new Intent(a,TransRideActivity.class);break;case"OPEN_FOOD":i=new Intent(a,TransFoodActivity.class);break;case"OPEN_SHOP":i=new Intent(a,TransShopActivity.class);break;case"OPEN_PICKUP":i=new Intent(a,TransPickupActivity.class);break;case"OPEN_CHAT":i=new Intent(a,CustomerChatActivity.class);break;case"OPEN_HISTORY":i=new Intent(a,CustomerHistoryActivity.class);break;case"OPEN_PROFILE":i=new Intent(a,ProfileActivity.class);break;case"OPEN_TOPUP":i=new Intent(a,CustomerTopUpActivity.class);break;case"OPEN_ACTIVE_ORDER":i=new Intent(a,LiveOrderCenterActivity.class);break;case"OPEN_LOCATION_SETTINGS":i=new Intent(Settings.ACTION_LOCATION_SOURCE_SETTINGS);break;case"OPEN_OVERLAY":if(Build.VERSION.SDK_INT>=23)i=new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION, Uri.parse("package:"+a.getPackageName()));break;case"OPEN_SEARCH":i=new Intent(a,GlobalSearchActivity.class);break;case"OPEN_HELP":i=new Intent(a,CustomerSettingsActivity.class);break;} if(i!=null)a.startActivity(i); } }
